    ParticipationID UNIQUEIDENTIFIER NOT NULL,
    Sequence INT NOT NULL DEFAULT 0,
    CommentType NVARCHAR(20) NOT NULL DEFAULT N'Technical',
    DocumentReference NVARCHAR(255) NULL,
    Comment NVARCHAR(MAX) NOT NULL,
    ProposedChange NVARCHAR(MAX) NULL,
    CONSTRAINT PK_BallotComment PRIMARY KEY (ID),
    CONSTRAINT FK_BallotComment_Contest FOREIGN KEY (ContestID) REFERENCES [${flyway:defaultSchema}].[Contest](ID),
    CONSTRAINT FK_BallotComment_Participation FOREIGN KEY (ParticipationID) REFERENCES [${flyway:defaultSchema}].[Participation](ID),
    CONSTRAINT CK_BallotComment_CommentType CHECK (CommentType IN (N'General', N'Technical', N'Editorial'))
);
