        [DocumentVersion] = CASE WHEN @DocumentVersion_Clear = 1 THEN NULL ELSE ISNULL(@DocumentVersion, [DocumentVersion]) END,
        [DocumentFileID] = CASE WHEN @DocumentFileID_Clear = 1 THEN NULL ELSE ISNULL(@DocumentFileID, [DocumentFileID]) END,
        [RecirculationRound] = ISNULL(@RecirculationRound, [RecirculationRound]),
        [PriorElectionID] = CASE WHEN @PriorElectionID_Clear = 1 THEN NULL ELSE ISNULL(@PriorElectionID, [PriorElectionID]) END
    WHERE
        [ID] = @ID

    -- Check if the update was successful
    IF @@ROWCOUNT = 0
        -- Nothing was updated, return no rows, but column structure from base view intact, semantically correct this way.
        SELECT TOP 0 * FROM [${flyway:defaultSchema}].[vwStandardsBallotElections] WHERE 1=0
    ELSE
